import{_ as a,a0 as o,w as i,s as l,ao as r,I as p,x as n,a1 as s,A as e}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const w=JSON.parse('{"title":"開啓 Ubuntu 系統自動升級 | LCTT x X-CMD","titleTemplate":false,"description":"開啓 Ubuntu 系統自動升級 | LCTT (201509) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"開啓 Ubuntu 系統自動升級 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"開啓 Ubuntu 系統自動升級 | LCTT (201509) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201509/20150916 Enable Automatic System Updates In Ubuntu","title":"開啓 Ubuntu 系統自動升級","tag":"201509","desc":""},"relativePath":"201509/20150916 Enable Automatic System Updates In Ubuntu.md","filePath":"[post].md"}'),d={name:"201509/20150916 Enable Automatic System Updates In Ubuntu.md"};function m(b,t,f,U,T,g){const u=o("Link");return i(),l("div",null,[t[16]||(t[16]=r('<h1 id="開啓-ubuntu-系統自動升級" tabindex="-1">開啓 Ubuntu 系統自動升級 <a class="header-anchor" href="#開啓-ubuntu-系統自動升級" aria-label="Permalink to “開啓 Ubuntu 系統自動升級”">​</a></h1><p>在學習如何開啓Ubuntu系統自動升級之前，先解釋下為什麼需要自動升級。</p><p>默認情況下，ubuntu每天一次檢查更新。但是一週只會彈出一次軟件升級提醒，除非當有安全性升級時，才會立即彈出。所以，如果你已經使用Ubuntu一段時間，你肯定很熟悉這個畫面：</p><p><img src="http://itsfoss.itsfoss.netdna-cdn.com/wp-content/uploads/2015/09/Software-Update-Ubntu.png" alt="Ubuntu軟件升級提醒"></p><p>但是做為一個正常桌面用户，根本不會去關心有什麼更新細節。而且這個提醒完全就是浪費時間，你肯定信任Ubuntu提供的升級補丁，對不對？所以，大部分情況你肯定會選擇“現在安裝”，對不對？</p><p>所以，你需要做的就只是點一下升級按鈕。現在，明白為什麼需要自動系統升級了吧？開啓自動系統升級意味着所有最新的更新都會自動下載並安裝，並且沒有請求確認。是不是很方便？</p><h3 id="開啓ubuntu自動升級" tabindex="-1">開啓Ubuntu自動升級 <a class="header-anchor" href="#開啓ubuntu自動升級" aria-label="Permalink to “開啓Ubuntu自動升級”">​</a></h3><p>演示使用Ubuntu15.04，Ubuntu 14.04步驟類似。</p><p>打開Unity Dash ，找到軟件&amp;更新：</p><p><img src="http://itsfoss.itsfoss.netdna-cdn.com/wp-content/uploads/2014/08/Software_Update_Ubuntu.jpeg" alt="Ubuntu 軟件升級設置"></p><p>打開軟件資源設置，切換到升級標籤：</p><p><img src="http://itsfoss.itsfoss.netdna-cdn.com/wp-content/uploads/2015/09/Software-Update-Ubntu-1.png" alt="Ubuntu 軟件升級設置"></p><p>可以發現，默認設置就是每日檢查並立即提醒安全升級。</p><p><img src="http://itsfoss.itsfoss.netdna-cdn.com/wp-content/uploads/2015/09/Software-Update-Ubntu-2.png" alt="改變軟件更新頻率"></p><p>改變 ‘當有安全升級’和‘當有其他升級’的選項為：下載並自動安裝。</p><p><img src="http://itsfoss.itsfoss.netdna-cdn.com/wp-content/uploads/2015/09/Software-Update-Ubntu-3.png" alt="Automatic updates in Ubuntu"></p>',16)),p("p",null,[t[1]||(t[1]=n("關閉對話框完成設定。這樣每次Ubuntu檢查更新後就會自動升級。事實上，這篇文章十分類似",-1)),s(u,{href:"http://itsfoss.com/ubuntu-notify-updates-frequently/"},{default:e(()=>[...t[0]||(t[0]=[n("改變Ubuntu升級提醒頻率",-1)])]),_:1}),t[2]||(t[2]=n("。",-1))]),t[17]||(t[17]=p("p",null,"你喜歡自動升級還是手動安裝升級呢？歡迎評論。",-1)),t[18]||(t[18]=p("hr",null,null,-1)),p("p",null,[t[4]||(t[4]=n("via: ",-1)),s(u,{href:"http://itsfoss.com/automatic-system-updates-ubuntu/"},{default:e(()=>[...t[3]||(t[3]=[n("http://itsfoss.com/automatic-system-updates-ubuntu/",-1)])]),_:1})]),p("p",null,[t[8]||(t[8]=n("作者：",-1)),s(u,{href:"http://itsfoss.com/author/abhishek/"},{default:e(()=>[...t[5]||(t[5]=[n("Abhishek",-1)])]),_:1}),t[9]||(t[9]=n(" 譯者：",-1)),s(u,{href:"http://vicyu.net"},{default:e(()=>[...t[6]||(t[6]=[n("Vic020/VicYu",-1)])]),_:1}),t[10]||(t[10]=n(" 校對：",-1)),s(u,{href:"https://github.com/wxy"},{default:e(()=>[...t[7]||(t[7]=[n("wxy",-1)])]),_:1})]),p("p",null,[t[13]||(t[13]=n("本文由 ",-1)),s(u,{href:"https://github.com/LCTT/TranslateProject"},{default:e(()=>[...t[11]||(t[11]=[n("LCTT",-1)])]),_:1}),t[14]||(t[14]=n(" 原創編譯，",-1)),s(u,{href:"https://linux.cn/"},{default:e(()=>[...t[12]||(t[12]=[n("Linux中國",-1)])]),_:1}),t[15]||(t[15]=n(" 榮譽推出",-1))])])}const S=a(d,[["render",m]]);export{w as __pageData,S as default};
